const repoPath = state.repoPath;
if (!repoPath) {
  console.error('[ranker] repoPath is not set');
  return { huntTargets: [] };
}

const { readdirSync, readFileSync, statSync } = await import('node:fs');
const { join, relative } = await import('node:path');

// Load prefilter config
const configPath = process.env.PREFILTER_CONFIG;
if (!configPath) {
  console.error('[ranker] PREFILTER_CONFIG is not set');
  return { huntTargets: [] };
}

let prefilterConfig;
try {
  prefilterConfig = JSON.parse(readFileSync(configPath, 'utf-8'));
} catch (e) {
  console.error('[ranker] Failed to load prefilter config:', e.message);
  return { huntTargets: [] };
}

const { chunkSize = 50, topN = 5, subsystems = [] } = prefilterConfig;

const SCAN_DIRS = ['libavcodec', 'libavformat', 'libavfilter'];

function collectCFiles(dir, files = []) {
  let entries;
  try { entries = readdirSync(dir, { withFileTypes: true }); } catch (e) { return files; }
  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      collectCFiles(full, files);
    } else if (entry.name.endsWith('.c')) {
      files.push(full);
    }
  }
  return files;
}

// Collect all .c files
const allCFiles = [];
for (const dir of SCAN_DIRS) {
  collectCFiles(join(repoPath, dir), allCFiles);
}
console.log(`[ranker] Collected ${allCFiles.length} .c files from ${SCAN_DIRS.join(', ')}`);

// Group by top-level directory
const filesByDir = new Map();
for (const f of allCFiles) {
  const rel = relative(repoPath, f);
  const topDir = rel.split('/')[0];
  if (!filesByDir.has(topDir)) filesByDir.set(topDir, []);
  filesByDir.get(topDir).push(f);
}

// Apply subsystem quotas — sort by file size within each subsystem (neutral complexity proxy)
const selected = [];
const assignedDirs = new Set();

for (const { dir, quota } of subsystems) {
  if (dir === '*') continue;
  const files = filesByDir.get(dir) || [];
  assignedDirs.add(dir);
  const bySize = files
    .map(f => ({ f, size: statSync(f).size }))
    .sort((a, b) => b.size - a.size)
    .slice(0, quota)
    .map(x => x.f);
  selected.push(...bySize);
  const top1 = bySize.length > 0 ? relative(repoPath, bySize[0]) : 'none';
  console.log(`[ranker] ${dir}: ${bySize.length}/${files.length} (quota=${quota}, largest=${top1})`);
}

// Handle catch-all (*) for remaining dirs
const catchAll = subsystems.find(s => s.dir === '*');
if (catchAll) {
  const remainingFiles = [];
  for (const [dir, files] of filesByDir) {
    if (!assignedDirs.has(dir)) remainingFiles.push(...files);
  }
  const bySize = remainingFiles
    .map(f => ({ f, size: statSync(f).size }))
    .sort((a, b) => b.size - a.size)
    .slice(0, catchAll.quota)
    .map(x => x.f);
  selected.push(...bySize);
  if (bySize.length > 0) {
    console.log(`[ranker] * (others): ${bySize.length}/${remainingFiles.length} (quota=${catchAll.quota})`);
  }
}

console.log(`[ranker] Pre-filter → ${selected.length} candidates (subsystem quota)`);

// LLM ranking
const chunks = [];
for (let i = 0; i < selected.length; i += chunkSize) {
  chunks.push(selected.slice(i, i + chunkSize));
}

const allTargets = [];
const specialistGuide = process.env.SPECIALIST_GUIDE || 'Focus on: general security vulnerabilities.';

for (let ci = 0; ci < chunks.length; ci++) {
  const chunk = chunks[ci];
  const relFiles = chunk.map(c => relative(repoPath, c));
  console.log(`[ranker] LLM chunk ${ci + 1}/${chunks.length} (${relFiles.length} files)`);

  const prompt = [
    'You are a security researcher ranking C files for vulnerability hunting.',
    `Specialist focus: ${specialistGuide}`,
    '',
    `Repository: ${repoPath}`,
    '',
    'Rate each file (0.0-1.0) on how likely it contains vulnerabilities matching the specialist focus:',
    '- surface: Complexity of input parsing or the targeted vulnerability class',
    '- influence: Pipeline reach — how many code paths pass through this file',
    '- reachability: Whether attacker-controlled input reaches this code',
    '',
    'Priority = surface*0.5 + influence*0.2 + reachability*0.3',
    '',
    'Files:',
    relFiles.map((f, i) => `${i + 1}. ${f}`).join('\n'),
    '',
    'Return ONLY a JSON array:',
    '[{"filePath":"relative/path","surface":0.8,"influence":0.5,"reachability":0.7,"reason":"brief"},...]'
  ].join('\n');

  const response = await model.invoke([{ role: 'user', content: prompt }]);
  const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);

  try {
    const jsonMatch = content.match(/\[[\s\S]*\]/);
    if (!jsonMatch) { console.error('[ranker] No JSON in chunk', ci + 1); continue; }
    const scored = JSON.parse(jsonMatch[0]);
    for (const item of scored) {
      const surface = Math.min(Math.max(Number(item.surface) || 0, 0), 1);
      const influence = Math.min(Math.max(Number(item.influence) || 0, 0), 1);
      const reachability = Math.min(Math.max(Number(item.reachability) || 0, 0), 1);
      const score = surface * 0.5 + influence * 0.2 + reachability * 0.3;
      allTargets.push({ filePath: item.filePath, score: Math.round(score * 1000) / 1000, reason: item.reason || '' });
    }
  } catch (e) {
    console.error('[ranker] Parse error chunk', ci + 1, ':', e.message);
  }
}

const llmTop = allTargets.sort((a, b) => b.score - a.score).slice(0, topN);

console.log(`[ranker] Final: top ${llmTop.length} from ${allTargets.length} LLM-ranked`);
if (llmTop.length > 0) console.log(`[ranker] #1: ${llmTop[0].filePath} (score=${llmTop[0].score})`);
return { huntTargets: llmTop };

const target = state.currentTarget;
if (!target) {
  console.warn('[hunter] No currentTarget in state');
  return { huntResults: [] };
}

const { readFileSync } = await import('node:fs');
const { join, isAbsolute } = await import('node:path');

let fileContent = '';
try {
  const fullPath = isAbsolute(target.filePath)
    ? target.filePath
    : join(state.repoPath, target.filePath);
  fileContent = readFileSync(fullPath, 'utf-8');
} catch (e) {
  console.error(`[hunter] Failed to read ${target.filePath}:`, e.message);
  return { huntResults: [{ filePath: target.filePath, specialist: 'generic', findings: [], confidence: 0 }] };
}

// SPECIALIST 環境変数でオーバーライド（ローテーション方式）
const envSpecialist = process.env.SPECIALIST;
const ext = (target.filePath.split('.').pop() || '').toLowerCase();
const lowerPath = target.filePath.toLowerCase();
const autoSpecialist = ['c', 'cpp', 'h', 'hpp'].includes(ext) ? 'memory_safety'
  : ['go', 'rs'].includes(ext) ? 'concurrency'
  : ['py', 'js', 'ts', 'jsx', 'tsx'].includes(ext) ? 'injection'
  : lowerPath.includes('crypto') || lowerPath.includes('ssl') || lowerPath.includes('tls') ? 'cryptography'
  : 'generic';
const specialist = envSpecialist || autoSpecialist;

const priorAttempts = (state.reflexionHistory || []).filter(h => h.target === target.filePath);
const gradientHint = priorAttempts.length > 0
  ? '\n\nPREVIOUS ATTEMPTS FAILED. Adjust your hypothesis based on these gradients:\n' + priorAttempts.map(h => `Attempt ${h.attempt}: ${h.verbalGradient}`).join('\n')
  : '';

const guide = process.env.SPECIALIST_GUIDE || 'Focus on: general security vulnerabilities.';

const hunterPrompt = `You are a security researcher specializing in ${specialist.replace(/_/g, ' ')} vulnerabilities.

File: ${target.filePath}
Priority score: ${target.score} — ${target.reason}

${guide}${gradientHint}

Analyze the following source code and identify ALL potential security vulnerabilities.
For each finding, assign evidence level: 1=theoretical possibility, 2=plausible exploit path with clear mechanism.

Source code:
\`\`\`
${fileContent.slice(0, 8000)}
\`\`\`

IMPORTANT — Accuracy requirements:
- Line numbers must be EXACT. Quote the actual vulnerable source line in your hypothesis. Do NOT estimate.
- If you cannot identify the exact line, set evidenceLevel to 0 and omit the finding.

Return ONLY a JSON object (no explanation, no markdown):
{"specialist":"${specialist}","confidence":0.0,"findings":[{"type":"vulnerability type","severity":"low|medium|high|critical","description":"what the vulnerability is","line":1,"column":null,"hypothesis":"how this could be exploited","evidenceLevel":1}]}`;

const localMessages = [{ role: 'user', content: hunterPrompt }];
const response = await model.invoke(localMessages);
const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);

let findings = [];
let confidence = 0;
let specialistResult = specialist;

try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    findings = Array.isArray(parsed.findings) ? parsed.findings : [];
    confidence = Math.min(Math.max(Number(parsed.confidence) || 0, 0), 1);
    specialistResult = parsed.specialist || specialist;
  }
} catch (e) {
  console.error(`[hunter] Failed to parse findings for ${target.filePath}:`, e.message);
}

console.log(`[hunter:${specialist}] ${target.filePath} → ${findings.length} findings (confidence=${confidence})`);
return { huntResults: [{ filePath: target.filePath, specialist: specialistResult, findings, confidence }] };

const { readFileSync } = await import('node:fs');
const { join, isAbsolute } = await import('node:path');

const CONFIDENCE_THRESHOLD = 0.7;
const allFindings = state.huntResults.flatMap(r => {
  if (r.confidence < CONFIDENCE_THRESHOLD) {
    if (r.findings.length > 0) {
      console.log(`[verifier] Skipping ${r.filePath} (confidence=${r.confidence} < ${CONFIDENCE_THRESHOLD}, ${r.findings.length} findings discarded)`);
    }
    return [];
  }
  return r.findings.map(f => ({ ...f, filePath: r.filePath, specialist: r.specialist }));
});

const alreadyVerified = new Set((state.verifiedFindings || []).map(f => `${f.filePath}:${f.line}`));
const pendingFindings = allFindings.filter(f => !alreadyVerified.has(`${f.filePath}:${f.line}`));
console.log(`[verifier] Verifying ${pendingFindings.length} pending findings (${allFindings.length - pendingFindings.length} already verified) from ${state.huntResults.length} files`);

const verified = [];
const failed = [];

for (const finding of pendingFindings) {
  let fileContext = '';
  try {
    const fullPath = isAbsolute(finding.filePath)
      ? finding.filePath
      : join(state.repoPath, finding.filePath);
    const lines = readFileSync(fullPath, 'utf-8').split('\n');
    const start = Math.max(0, (finding.line || 1) - 40);
    const end = Math.min(lines.length, (finding.line || 1) + 40);
    fileContext = lines.slice(start, end).map((l, i) => `${start + i + 1}: ${l}`).join('\n');
  } catch (e) {
    fileContext = '(file not readable)';
  }

  const verifyPrompt = `You are an independent security auditor. Verify the following vulnerability finding.

File: ${finding.filePath}
Vulnerability type: ${finding.type}
Severity: ${finding.severity}
Description: ${finding.description}
Line: ${finding.line}${finding.column != null ? ':' + finding.column : ''}
Exploit hypothesis: ${finding.hypothesis}
Claimed evidence level: ${finding.evidenceLevel}

Code context:
\`\`\`
${fileContext}
\`\`\`

Independently assess:
1. Is this a real vulnerability or a false positive?
2. If valid, what evidence level is appropriate? (1=theoretical, 2=plausible exploit path with clear mechanism)
3. If invalid, state the exact reason.

CRITICAL PRINCIPLE: Base your assessment ONLY on what is directly visible in the code context above. If a validation, bounds check, or safety mechanism is claimed to exist but is NOT visible in the provided context, do NOT assume it provides protection — it may be absent or insufficient. When the relevant caller logic, allocation size, or constraint enforcement is outside the visible window, acknowledge that uncertainty rather than asserting correctness.

Return ONLY a JSON object (no explanation):
{"valid":true,"evidenceLevel":1,"reason":"brief assessment"}`;

  const localMessages = [{ role: 'user', content: verifyPrompt }];
  const response = await model.invoke(localMessages);
  const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);

  try {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error('No JSON in response');
    const result = JSON.parse(jsonMatch[0]);
    if (result.valid) {
      verified.push({ ...finding, evidenceLevel: result.evidenceLevel || finding.evidenceLevel, verifiedAt: new Date().toISOString() });
      console.log(`[verifier] PASS: ${finding.type} in ${finding.filePath}:${finding.line} (Lv${result.evidenceLevel})`);
    } else {
      failed.push({ finding, reason: result.reason || 'Rejected by verifier' });
      console.log(`[verifier] FAIL: ${finding.type} in ${finding.filePath}:${finding.line} — ${result.reason}`);
    }
  } catch (e) {
    console.error(`[verifier] Parse error for ${finding.filePath}:${finding.line}:`, e.message);
    failed.push({ finding, reason: 'Verifier response parse error' });
  }
}

console.log(`[verifier] Results: ${verified.length} verified, ${failed.length} failed`);
return { verifiedFindings: verified, _failedFindings: failed };

const failed = state._failedFindings || [];
const CONFIDENCE_THRESHOLD = 0.7;

// findings=0 または低 confidence のファイル — _failedFindings には入らないが Reflexion が必要
const noFindingsFiles = (state.huntResults || []).filter(r =>
  r.findings.length === 0 || r.confidence < CONFIDENCE_THRESHOLD
).filter(r => !failed.some(f => f.finding.filePath === r.filePath));

console.log(`[analyst] Generating verbal gradients for ${failed.length} failed findings + ${noFindingsFiles.length} no-findings/low-confidence files`);

const reflexionEntries = [];

for (const { finding, reason } of failed) {
  const analysisPrompt = `A vulnerability hypothesis was rejected by an independent verifier.

File: ${finding.filePath}
Vulnerability type: ${finding.type}
Original hypothesis: ${finding.hypothesis}
Rejection reason: ${reason}

Analyze WHY this hypothesis failed and generate a corrected hypothesis direction (verbal gradient).
Be specific:
- What assumption was wrong?
- What should be investigated differently?
- What additional context or code path should be examined?

Respond with a concrete, actionable verbal gradient (2-4 sentences).`;

  const localMessages = [{ role: 'user', content: analysisPrompt }];
  const response = await model.invoke(localMessages);
  const verbalGradient = typeof response.content === 'string' ? response.content.trim() : JSON.stringify(response.content);

  const attempt = (state.reflexionHistory || []).filter(h => h.target === finding.filePath).length + 1;
  reflexionEntries.push({
    target: finding.filePath,
    attempt,
    failureReason: reason,
    verbalGradient,
    timestamp: new Date().toISOString()
  });
  console.log(`[analyst] Gradient for ${finding.filePath} attempt ${attempt}: ${verbalGradient.slice(0, 80)}...`);
}

for (const result of noFindingsFiles) {
  const reasonLabel = result.findings.length === 0 ? 'no_findings' : `low_confidence_${result.confidence}`;

  const analysisPrompt = `A security scanner found no confirmed vulnerabilities in the following file.

File: ${result.filePath}
Previous scan: ${result.findings.length === 0
  ? 'No findings generated at all.'
  : `${result.findings.length} finding(s) discarded due to low confidence (${result.confidence}).`
}

Generate a verbal gradient (2-4 sentences) for a focused re-investigation:
- What specific patterns should be re-examined?
- What corner cases might hide real vulnerabilities?

Respond with a concrete, actionable verbal gradient.`;

  const localMessages = [{ role: 'user', content: analysisPrompt }];
  const response = await model.invoke(localMessages);
  const verbalGradient = typeof response.content === 'string' ? response.content.trim() : JSON.stringify(response.content);

  const attempt = (state.reflexionHistory || []).filter(h => h.target === result.filePath).length + 1;
  reflexionEntries.push({
    target: result.filePath,
    attempt,
    failureReason: reasonLabel,
    verbalGradient,
    timestamp: new Date().toISOString()
  });
  console.log(`[analyst] Gradient for ${result.filePath} (${reasonLabel}) attempt ${attempt}: ${verbalGradient.slice(0, 80)}...`);
}

const MAX_RETRY_FILES = 5;
const failedFilePaths = new Set(failed.map(f => f.finding.filePath));
const noFindingsFilePaths = new Set(noFindingsFiles.map(r => r.filePath));

const retryTargets = (state.huntTargets || []).filter(t =>
  failedFilePaths.has(t.filePath) || noFindingsFilePaths.has(t.filePath)
).slice(0, MAX_RETRY_FILES);

console.log(`[analyst] Scheduling retry for ${retryTargets.length} targets`);
return {
  reflexionHistory: reflexionEntries,
  huntTargets: retryTargets,
  huntResults: []
};

const findings = state.verifiedFindings || [];
console.log(`[exploiter] Processing ${findings.length} verified findings`);

const exploited = [];

for (const finding of findings) {
  if ((finding.evidenceLevel || 0) < 2) {
    console.log(`[exploiter] SKIP: ${finding.type} in ${finding.filePath}:${finding.line} (evidenceLevel=${finding.evidenceLevel} < 2)`);
    exploited.push({ ...finding, poc: null, exploitStatus: 'insufficient_evidence' });
    continue;
  }

  const exploitPrompt = [
    'Generate a minimal proof-of-concept for the following vulnerability.',
    `Finding: ${JSON.stringify(finding)}`,
    'Requirements:',
    '- Minimal code demonstrating the vulnerability mechanism',
    '- Include comments explaining the exploit mechanism',
    '- Do NOT include destructive payloads or real attack payloads',
    '- Keep it conceptual and educational',
    'Return ONLY a JSON object (no explanation, no markdown):',
    '{"pocCode":"code here","language":"language name","exploitMechanism":"brief explanation"}'
  ].join('\n');

  const localMessages = [{ role: 'user', content: exploitPrompt }];
  const response = await model.invoke(localMessages);
  const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);

  let poc = null;
  try {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    poc = jsonMatch ? JSON.parse(jsonMatch[0]) : null;
  } catch (e) {
    console.error(`[exploiter] Failed to parse PoC for ${finding.filePath}:${finding.line}:`, e.message);
  }

  const status = poc ? 'generated' : 'failed';
  console.log(`[exploiter] ${status.toUpperCase()}: ${finding.type} in ${finding.filePath}:${finding.line}`);
  exploited.push({ ...finding, poc, exploitStatus: status });
}

console.log(`[exploiter] Generated ${exploited.filter(e => e.exploitStatus === 'generated').length}/${exploited.length} PoCs`);
return { _exploitedFindings: exploited };

const findings = state._exploitedFindings && state._exploitedFindings.length > 0
  ? state._exploitedFindings
  : state.verifiedFindings || [];
const repoPath = state.repoPath || '(unknown)';
const reflexionCount = (state.reflexionHistory || []).length;

console.log(`[reporter] Generating report for ${findings.length} findings (${reflexionCount} reflexion iterations)`);

const reportPrompt = [
  'Generate a security vulnerability report in Markdown format.',
  `Repository: ${repoPath}`,
  `Total findings: ${findings.length}`,
  `Reflexion iterations applied: ${reflexionCount}`,
  '',
  'Findings:',
  JSON.stringify(findings, null, 2),
  '',
  'Required report structure:',
  '# Security Audit Report',
  '## Executive Summary',
  '- Scan target, total findings count, breakdown by severity',
  '## Findings',
  '### [SEVERITY] filename:line',
  '- Description, evidence level, PoC (if available), remediation recommendation',
  '## Methodology',
  '- Reflexion loop iterations, specialist modes used',
  '## Appendix',
  '- reflexionHistory summary'
].join('\n');

const localMessages = [{ role: 'user', content: reportPrompt }];
const response = await model.invoke(localMessages);
const markdownReport = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);

const sarifReport = {
  version: '2.1.0',
  $schema: 'https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json',
  runs: [{
    tool: {
      driver: {
        name: 'SGM-SourceHunt',
        version: '1.0.0',
        informationUri: 'https://github.com/akudo7/SceneGraphManager'
      }
    },
    results: findings.map((f, idx) => ({
      ruleId: f.type || 'unknown',
      level: f.severity === 'critical' ? 'error'
        : f.severity === 'high' ? 'warning'
        : 'note',
      message: { text: f.description || '' },
      locations: [{
        physicalLocation: {
          artifactLocation: { uri: f.filePath || '' },
          region: { startLine: f.line || 1 }
        }
      }]
    }))
  }]
};

const byEvidenceLevel = findings.reduce((acc, f) => {
  const lv = String(f.evidenceLevel || 'unknown');
  acc[lv] = (acc[lv] || 0) + 1;
  return acc;
}, {});

const bySeverity = findings.reduce((acc, f) => {
  const sev = f.severity || 'unknown';
  acc[sev] = (acc[sev] || 0) + 1;
  return acc;
}, {});

const pocGenerated = findings.filter(f => f.exploitStatus === 'generated').length;

const finalReport = JSON.stringify({
  markdown: markdownReport,
  sarif: sarifReport,
  json: findings,
  stats: {
    totalFindings: findings.length,
    byEvidenceLevel,
    bySeverity,
    pocGenerated,
    reflexionIterations: reflexionCount,
    repoPath
  }
}, null, 2);

console.log(`[reporter] Report generated (${markdownReport.length} chars markdown, ${findings.length} findings, ${pocGenerated} PoCs)`);
return {
  finalReport,
  messages: [{ role: 'assistant', content: markdownReport }]
};

if (!state.huntTargets || state.huntTargets.length === 0) {
  console.warn('[fanOut] No huntTargets — routing to __end__');
  return '__end__';
}
console.log(`[fanOut] Dispatching ${state.huntTargets.length} hunters`);
return state.huntTargets.map(target => new Send('hunter_node', { ...state, currentTarget: target }));

const MAX_REFLEXION = 2;
const CONFIDENCE_THRESHOLD = 0.7;
const failedFindings = state._failedFindings || [];
const huntResults = state.huntResults || [];
const reflexionHistory = state.reflexionHistory || [];

// findings=0 または低 confidence のファイル（Reflexion の機会が必要）
const needsRetryFiles = huntResults.filter(r =>
  r.findings.length === 0 || r.confidence < CONFIDENCE_THRESHOLD
);

const hasRetryableFailures = failedFindings.some(f => {
  const attempts = reflexionHistory.filter(h => h.target === f.finding.filePath).length;
  return attempts < MAX_REFLEXION;
});

const hasRetryableNoFindings = needsRetryFiles.some(r => {
  const attempts = reflexionHistory.filter(h => h.target === r.filePath).length;
  return attempts < MAX_REFLEXION;
});

if (!hasRetryableFailures && !hasRetryableNoFindings) {
  if (failedFindings.length === 0 && needsRetryFiles.length === 0) {
    console.log('[reflexion] No failures — proceeding to exploiter');
  } else {
    console.log(`[reflexion] MAX_REFLEXION (${MAX_REFLEXION}) reached for all targets — proceeding to exploiter`);
  }
  return 'exploiter_node';
}

const pendingFailed = failedFindings.filter(f => {
  const attempts = reflexionHistory.filter(h => h.target === f.finding.filePath).length;
  return attempts < MAX_REFLEXION;
});
const pendingNoFindings = needsRetryFiles.filter(r => {
  const attempts = reflexionHistory.filter(h => h.target === r.filePath).length;
  return attempts < MAX_REFLEXION;
});

console.log(`[reflexion] ${pendingFailed.length} failed + ${pendingNoFindings.length} no-findings/low-confidence eligible for retry — routing to failure_analyst`);
return 'failure_analyst_node';

if (!state.huntTargets || state.huntTargets.length === 0) {
  console.warn('[retryFanOut] No retry targets — routing to __end__');
  return '__end__';
}
console.log(`[retryFanOut] Retrying ${state.huntTargets.length} hunters with verbal gradients`);
return state.huntTargets.map(target => new Send('hunter_node', { ...state, currentTarget: target }));
